head.script:
scwin.trigger1_onclick = function(e) {
    //alert(dataMap1.get("USER_YN"));
    al = dataMap1.get("USER_YN");
};
scwin.unitTest = function() {
    //Unit
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 1. 샘플파일 실행 후 DataMap.get 버튼을 클릭한다.
    //1. After running the sample file, click the DataMap.get button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 1. Y 값을 리턴한다.
    //1. Return the Y value.
    WebSquare.wUnit.addCommand("assert", "al", "Y");
    WebSquare.wUnit.addCommand("pause", "500");
    // Test step 2. data의 체크를 해제하고 DataMap.get 버튼을 클릭한다.
    //2. Uncheck the data and click the DataMap.get button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('chk1_input_0').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "1000");
    // verify step 2. N 값을 리턴한다.(이전에는 Y 값을 리턴함)
    //2. Return the value of N (previously it returns the value of Y)
    WebSquare.wUnit.addCommand("assert", "al", "N");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run test and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.al = undefined;
    //Function unitTest
    //Created By: Sang.do
    //Created By: 09-Feb-2018
    //end unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
